  (9, 'სისხლის მიმოქცევის სისტემის დაავადებები', 'I00', 'I99'),
  (10, 'სასუნთქი სისტემის დაავადებები', 'J00', 'J99'),
  (11, 'საჭმლის მომნელებელი სისტემის დაავადებები', 'K00', 'K93'),
  (12, 'კანისა და კანქვეშა ქსოვილების დაავადებები', 'L00', 'L99'),
  (13, 'ძვალ - კუნთოვანი სისტემის და შემადგენელი ქსოვილების დაავადებები', 'M00', 'M99'),
  (14, 'შარდ - სასქესო სისტემის დაავადებები', 'N00', 'N99'),
